"""Publish only a new final-evaluator directory and CPU watcher; live science untouched."""
import base64,hashlib,json,os,subprocess,socket,time
from pathlib import Path
PAYLOAD={'final_eval.py': {'base64': '', 'sha256': 'e7ef18feb95acc839a30cc044a563696c754cf692e8f6613587cd05ef8edbdab'}, 'boundary_supervisor.py': {'base64': '', 'sha256': 'e80cbcfed752a0f7995f0719d72cd041fe2938712ce4419b0d7fa2bca61f8069'}, 'final_worker.py': {'base64': '', 'sha256': '28ffffe374b0bb8b1a920a415ca844dceeedb5a5126aaf6528f2e0bb7b890bf5'}, 'README.md': {'base64': '', 'sha256': 'adaf8c8e97f211f16fa9815e614cd33cf929537ca6af49cc3f0995a6fe5d6518'}, 'test_contract.py': {'base64': '', 'sha256': '64877f22a4ebd69e74ed0a9fa6d47342116494aaa8d07772a4c28fabf498bf29'}}
COMMIT='0b3acde'
base=Path('/dataset/shaoshitong/recursive-bran-a-h100-20261012')
assert socket.gethostname().split('.')[0]=='h100-11'
owner=Path('/proc/3714909');stat=(owner/'stat').read_text().rsplit(')',1)[1].split()
assert owner.stat().st_uid==0 and int(stat[19])==658086351
config=json.loads((base/'receipts/configuration.json').read_text())
assert config['run_id']=='1c806d15752d44a7ac99687f0737d7e3'
assert config['config_sha256']=='653193a4eb06bd28667f78ac14a66a2d1c97200ca8199b8521dcc2d3de35b319'
folder=base/('source-final51713-'+COMMIT);folder.mkdir(exist_ok=True)
verified={}
for name,record in PAYLOAD.items():
 assert Path(name).name==name
 raw=base64.b64decode(record['base64']);assert hashlib.sha256(raw).hexdigest()==record['sha256']
 path=folder/name
 if path.exists():assert path.read_bytes()==raw,'Never hot-edit deployed helper'
 else:path.write_bytes(raw)
 verified[name]=hashlib.sha256(path.read_bytes()).hexdigest();assert verified[name]==record['sha256']
control=base/('final51713-supervisor-'+COMMIT);control.mkdir(exist_ok=True)
runtime='/dataset/shaoshitong/search-r1-rl/bapo-aligned-cohost-node11-v11-20261009'
python=runtime+'/env/bin/python';env=dict(os.environ,CUDA_VISIBLE_DEVICES='',PYTHONDONTWRITEBYTECODE='1',PYTHONPATH=str(folder)+':'+str(base/'source-71d4e69')+':'+str(base/'source-71d4e69/release/recursive_bran_a/h100_migration'))
env.pop('LD_LIBRARY_PATH',None)
commands=[[python,'-B','-m','unittest','discover','-s',str(folder),'-p','test_contract.py','-v'],[python,'-B','-c','import final_worker,torch; assert not torch.cuda.is_initialized(); print("FINAL_WORKER_IMPORT_CPU_ONLY_PASS")']]
results=[]
for cmd in commands:
 p=subprocess.run(cmd,env=env,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,timeout=120)
 results.append(dict(command=cmd,rc=p.returncode,stdout=p.stdout,stderr=p.stderr))
 assert p.returncode==0,results[-1]
publication=dict(time=time.time(),payload_commit=COMMIT,files=verified,CPU_checks=results,deployed=str(folder),live_training_modified=False)
(control/'publication.json').write_text(json.dumps(publication,indent=2))
assert not (control/'watcher-launch.json').exists(),'Do not duplicate a watcher; inspect the original launch'
log=(control/'watcher.log').open('ab')
child=subprocess.Popen([python,'-B','-u',str(folder/'boundary_supervisor.py'),'--control',str(control)],env=env,stdout=log,stderr=log,start_new_session=True)
for attempt in range(50):
 if (control/'status.json').exists():break
 if child.poll() is not None:raise RuntimeError('CPU watcher early exit; inspect watcher.log')
 time.sleep(.1)
assert (control/'status.json').exists()
stat=(Path('/proc')/str(child.pid)/'stat').read_text().rsplit(')',1)[1].split()
launch=dict(time=time.time(),pid=child.pid,uid=os.getuid(),starttick=int(stat[19]),source_commit=COMMIT,status=json.loads((control/'status.json').read_text()),GPU_initialized=False,control=str(control))
(control/'watcher-launch.json').write_text(json.dumps(launch,indent=2))
print(json.dumps(dict(publication=publication,launch=launch)),flush=True)
